<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import {refreshAll} from '$app/navigation';import {request,recordName} from '#lib/client/api.ts';import type {Row} from '#lib/client/types.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';
  let {publications=[]}:{publications?:Row[]}=$props();let files:FileList|undefined=$state();let publicationId=$state('');let busy=$state(false);let error=$state('');let uploaded:Row[]=$state([]);let input:HTMLInputElement;const confirmedFiles=new Set<string>();
  async function upload(event:SubmitEvent){event.preventDefault();if(!files?.length||busy)return;busy=true;error='';try{for(const file of Array.from(files)){const fingerprint=file.name+':'+file.size+':'+file.lastModified;if(confirmedFiles.has(fingerprint))continue;if(file.size>4_000_000)throw new Error(`${file.name} ist größer als 4 MB. Bitte verkleinern oder aufteilen und erneut auswählen.`);const form=new FormData();form.append('file',file);if(publicationId)form.append('publication_id',publicationId);const result=await request('/api/v1/portal/uploads',form);uploaded=[...uploaded,{...(result.document||result),original_name:file.name}];confirmedFiles.add(fingerprint);}confirmedFiles.clear();files=undefined;if(input)input.value='';await refreshAll().catch(()=>{});}catch(e){error=e instanceof DOMException&&['NotReadableError','NotFoundError'].includes(e.name)?'Die Datei wurde nach dem Auswählen geändert oder ist nicht mehr erreichbar. Bitte wählen Sie sie erneut aus.':e instanceof Error?e.message:'Die Datei konnte nicht übertragen werden. Bitte versuchen Sie es erneut.';}finally{busy=false;}}
</script>
<section class="panel mt"><header class="panel-header"><div><h2>Unterlagen an Schubert senden</h2><p>Zum Beispiel Fotos, Unterzeichnungen oder ergänzende Angaben zu Ihrem Vorhaben.</p></div><Icon name="upload" size={18}/></header><form class="panel-body" onsubmit={upload}>{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if publications.length}<div class="field mb"><label for="portal-upload-reference">Bezug · optional</label><select use:searchableSelect={publicationId} id="portal-upload-reference" bind:value={publicationId}><option value="">Allgemeine Unterlage zu meinem Vorhaben</option>{#each publications as publication}<option value={publication.id}>{recordName(publication)}</option>{/each}</select></div>{/if}<div class="field"><label for="portal-upload-files">Dateien oder Fotos *</label><input id="portal-upload-files" bind:this={input!} type="file" multiple bind:files accept=".pdf,.jpg,.jpeg,.png,.webp,.txt,.csv,.xlsx,.xml,.zip" required/><span class="field-help">Bis zu 4 MB je Datei. Ihre Unterlagen werden geschützt gespeichert und vor der weiteren Verwendung geprüft.</span></div><button class="btn primary mt" disabled={busy||!files?.length}>{busy?'Wird übertragen …':'Unterlagen übertragen'}<Icon name="upload" size={16}/></button>{#each uploaded as document}<div class="file-row mt" role="status"><Icon name="file" size={18}/><div class="file-info"><h3>{document.original_name}</h3><p>Empfangen. Die weitere Verwendung erfolgt nach der Dateiprüfung.</p><Status value={document.scan_status||document.status||'quarantine'}/></div></div>{/each}</form></section>
